            System.err.println("ReadBlock: blkIdx = " + currBlkIdx);
        }
        if (inStream == null) {
            throw new IOException("reading from an output buffer");
        }
        currRecIdx = 0;
        int offset = 0;
        int bytesNeeded = blockSize;
        while (bytesNeeded > 0) {
            long numBytes = inStream.read(blockBuffer, offset, bytesNeeded);
            //
            // NOTE
